import{_ as a,o as r,c as d,ag as e}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"TraeWork 中国版体验","description":"AI Agent 零基础教程","frontmatter":{"title":"TraeWork 中国版体验","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/05-traework.md","filePath":"guide/05-traework.md","lastUpdated":null}'),l={name:"guide/05-traework.md"};function i(o,t,h,n,s,c){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="traework-中国版体验" tabindex="-1">TraeWork 中国版体验 <a class="header-anchor" href="#traework-中国版体验" aria-label="Permalink to &quot;TraeWork 中国版体验&quot;">​</a></h1><blockquote><p>状态：正文完成；共同基准任务已实测（2026-08-12）</p><p>本机版本：0.1.47（安装目录 <code>TRAE SOLO CN</code>，窗口标题 <code>TraeWork CN</code>）</p><p>最后本机核对：2026-08-12；订阅核验：2026-08-11</p></blockquote><h2 id="_1-一句话结论" tabindex="-1">1. 一句话结论 <a class="header-anchor" href="#_1-一句话结论" aria-label="Permalink to &quot;1. 一句话结论&quot;">​</a></h2><p>「国内综合型」里<strong>对零基础门槛最低</strong>的选项之一：0 人工介入、无需配置模型、Work/Code/Design 三模式让新手按任务类型选入口。实测 5 分 51 秒完成 6/6 交付、消耗 37.71 积分。短板：本轮未留存审阅/差异截图（变更能力范围未验证）、具体模型名称未记录。</p><h2 id="_2-测试版本和地区" tabindex="-1">2. 测试版本和地区 <a class="header-anchor" href="#_2-测试版本和地区" aria-label="Permalink to &quot;2. 测试版本和地区&quot;">​</a></h2><ul><li>测试日期：2026-08-12（统一基准实测）；界面截图核验 2026-08-13</li><li>正式产品名称与测试入口：TraeWork 中国版（窗口标题 <code>TraeWork CN</code>）</li><li>地区版本：中国版（与 Trae CN 代码环境是不同产品线，本页只讲 TraeWork）</li><li>具体产品线：Work 综合任务模式（产品另有 Code / Design 模式）</li><li>账号区域与计费币种：中国区账号；人民币计价（积分制）</li><li>当前账号状态：正常（测试时）</li><li>官方服务是否覆盖当前地区：中国区官方运营</li><li>注册、登录与支付前提：手机号/账号注册；支付方式见官方</li><li>账号受限后的申诉与恢复入口：官方支持渠道（未触发）</li><li>桌面客户端版本：产品版本 0.1.47；可执行构建 2.3.68299</li><li>操作系统：Windows</li><li>官方下载来源：TRAE 中国区官网</li><li>入门分组：国内综合型 Agent</li><li>主要任务方向：工作 / 代码 / 设计（三模式）</li><li>开放与后台运行方式：云端（官方积分体系）</li><li>自主程度：中</li><li>建议基础：零基础</li><li>使用方案：Free / Lite / Pro / Pro+ / Ultra</li><li>官方订阅名称、价格与周期：Lite 单月 ¥49、连续包月 ¥45（新付费用户首月 ¥9.9）；Pro 单月 ¥99、连续包月 ¥89（首月 ¥59）；Pro+ 单月 ¥239、连续包月 ¥219；Ultra 单月 ¥699、连续包月 ¥629</li><li>套餐内用量单位：积分（Lite 每月 2,000 专属积分；Pro / Pro+ / Ultra 分别为 4,000 / 12,000 / 40,000 通用积分）</li><li>用量重置时间与结转规则：按月，详见官方计费文档</li><li>官方 API 是否另行计费：未核实到桌面版独立 API 计费</li><li>是否支持 BYOK：官方公开文档暂无 TraeWork 桌面版 BYOK/自定义模型说明；官方文档提到 Seed-2.1-Turbo、Seed-Code 享 2.5 折计费</li><li>免费额度及核验来源：Free 500 积分/月（官网价格页）</li><li>新用户或学生福利：官网价格页显示新人赠送 4,500 积分横幅；活动入口、到账条件与有效期<strong>发布前须用新账号在中国版桌面端复核</strong></li><li>最后核验日期：2026-08-11</li><li>测试者背景：作者</li></ul><h2 id="_3-下载、安装与首次启动" tabindex="-1">3. 下载、安装与首次启动 <a class="header-anchor" href="#_3-下载、安装与首次启动" aria-label="Permalink to &quot;3. 下载、安装与首次启动&quot;">​</a></h2><ul><li>下载和安装：中国区官网下载桌面客户端，安装顺利（本机安装于 <code>E:\\Program\\TRAE\\TRAE SOLO CN</code>）；</li><li>是否必须注册、登录或绑定其他服务：需要中国区账号登录；</li><li>首次权限提示：本轮未出现权限确认弹窗；</li><li>主界面导航：左上直接提供 <code>Work / Code / Design</code> 三模式切换，左侧新建任务、插件市场、设计系统、办公助理、任务列表，中间任务对话，底部统一输入区，导航直观；</li><li>新手从启动到完成第一个任务：新建任务 → 选择 Work 模式 → 选择工作目录 → 粘贴提示词 → 发送；</li><li>是否有只能通过 CLI/TUI 才能完成的重要能力：未发现。</li></ul><h2 id="_4-免费额度、订阅与计费" tabindex="-1">4. 免费额度、订阅与计费 <a class="header-anchor" href="#_4-免费额度、订阅与计费" aria-label="Permalink to &quot;4. 免费额度、订阅与计费&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>实际记录</th><th>官方来源</th><th>最后核验日期</th></tr></thead><tbody><tr><td>免费额度</td><td>Free 500 积分/月；页面显示新人赠送 4,500 积分（待复核）</td><td>TRAE 中国区定价</td><td>2026-08-11</td></tr><tr><td>官方订阅</td><td>Lite ¥45–49/月（首月 ¥9.9）；Pro ¥89–99/月（首月 ¥59）；Pro+ ¥219–239/月；Ultra ¥629–699/月</td><td>TRAE 中国区定价</td><td>2026-08-11</td></tr><tr><td>用量单位与重置规则</td><td>专属/通用积分；Lite 2,000、Pro 4,000、Pro+ 12,000、Ultra 40,000</td><td>TraeWork 积分计费说明</td><td>2026-08-11</td></tr><tr><td>新用户或学生福利</td><td>新人 4,500 积分活动，规则待复核</td><td>官网价格页</td><td>2026-08-11</td></tr><tr><td>API 或 BYOK</td><td>无公开 BYOK 说明；Seed 系列模型 2.5 折计费</td><td>官方文档</td><td>2026-08-11</td></tr></tbody></table><p><strong>实测补充</strong>：本轮实际消耗 37.71 积分（测试者确认），具体模型显示名称未记录。</p><h2 id="_5-核心能力" tabindex="-1">5. 核心能力 <a class="header-anchor" href="#_5-核心能力" aria-label="Permalink to &quot;5. 核心能力&quot;">​</a></h2><ul><li>能处理哪些材料：文档、文件、工作材料；统一基准任务中一次生成 6 份结构化 Markdown；</li><li>能调用哪些工具：文件系统、任务对话、产物导航（本轮用到）；代码与设计模式能力在界面中可见但未在共同任务中触发；</li><li>代表性功能：三模式入口、任务摘要与产物清单、Markdown 成品渲染；</li><li>哪些能力实际验证过：共同基准任务的完整交付；哪些只来自官方说明：Design 模式的完整能力、插件市场等生态。</li></ul><h2 id="_6-界面与工作方式" tabindex="-1">6. 界面与工作方式 <a class="header-anchor" href="#_6-界面与工作方式" aria-label="Permalink to &quot;6. 界面与工作方式&quot;">​</a></h2><ul><li>运行位置：官方中国版桌面应用（云端处理）；</li><li>用户如何观察和控制执行过程：中间任务对话区展示执行与结论卡片；右侧任务摘要与产物清单。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>观察记录</th><th>适用前提</th></tr></thead><tbody><tr><td>新手上手难度</td><td>低；三模式按任务类型选入口</td><td>—</td></tr><tr><td>账号与地区可用性</td><td>中国区账号正常</td><td>—</td></tr><tr><td>图形界面清晰度</td><td>三栏 + 顶部模式切换，办公入口（插件市场/自动化/办公助理/模板库）齐全</td><td>—</td></tr><tr><td>任务状态反馈</td><td>任务摘要 + 产物清单；最终摘要细节待截图</td><td>—</td></tr><tr><td>权限提示与确认</td><td>本轮 0 次</td><td>—</td></tr><tr><td>上下文处理</td><td>只读取 input 材料包，未发现越界读取</td><td>—</td></tr><tr><td>过程可控性</td><td>0 人工介入</td><td>—</td></tr><tr><td>结果定位与验证</td><td>产物 Markdown 直接渲染，阅读体验接近文档站点</td><td>—</td></tr><tr><td>生态与扩展</td><td>插件市场、自动化、办公助理、模板库入口可见</td><td>未逐一实测</td></tr></tbody></table><p>界面细节见 「界面讲解文档」(docs/11-interface-guides/02-traework-cn.md)。<strong>功能范围如实说明</strong>：概览/预览有截图证据；变更/差异/审阅环节本轮未留存截图，<strong>能力范围标注为「未验证」</strong>，界面中也未见与 WorkBuddy 类似的「文件变更 + diff」面板入口。</p><h2 id="_7-三类实测任务" tabindex="-1">7. 三类实测任务 <a class="header-anchor" href="#_7-三类实测任务" aria-label="Permalink to &quot;7. 三类实测任务&quot;">​</a></h2><h3 id="_7-1-共同基准任务-2026-08-12" tabindex="-1">7.1 共同基准任务（2026-08-12） <a class="header-anchor" href="#_7-1-共同基准任务-2026-08-12" aria-label="Permalink to &quot;7.1 共同基准任务（2026-08-12）&quot;">​</a></h3><h4 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h4><p>使用冻结的教程材料包（<code>input/</code> 7 份文件），整理 AI Agent 教程材料，生成六个指定交付文件并自检。</p><h4 id="完整输入" tabindex="-1">完整输入 <a class="header-anchor" href="#完整输入" aria-label="Permalink to &quot;完整输入&quot;">​</a></h4><p>冻结材料包 + <code>traework-prompt.md</code> 统一提示。</p><h4 id="执行过程" tabindex="-1">执行过程 <a class="header-anchor" href="#执行过程" aria-label="Permalink to &quot;执行过程&quot;">​</a></h4><p>打开 TraeWork → 选择 Work 综合任务模式 → 选择运行目录 → 保持默认模型与权限 → 粘贴统一提示发送。</p><h4 id="最终结果" tabindex="-1">最终结果 <a class="header-anchor" href="#最终结果" aria-label="Permalink to &quot;最终结果&quot;">​</a></h4><p>六份指定文件按顺序生成（07:56:07 首文件至 07:59:35 末文件），总用时 5 分 51 秒（测试者记录；首末文件间隔 3 分 28 秒）。</p><h4 id="验收情况" tabindex="-1">验收情况 <a class="header-anchor" href="#验收情况" aria-label="Permalink to &quot;验收情况&quot;">​</a></h4><ul><li>交付：6/6 一次通过，无权限确认、人工回复、中断、报错或重试；7/7 输入 SHA-256 与基线一致；</li><li>内容亮点：信息缺口分类清楚（D6–D9 标注为整理者推断）；待办可勾选；自检覆盖交付、权限、质量与未解决问题；</li><li>内容偏差：自行生成五部分、15 章目录，只能作为基准答卷不能替换正式 23 章框架；把部分 SVG/CSV 输入推导为「协议已完成」的表述强于材料可支持的程度；</li><li>指标：澄清 0 / 权限确认 0 / 人工回复 0 / 中断 0 / 报错 0 / 重试 0。</li></ul><table tabindex="0"><thead><tr><th>指标</th><th>记录</th></tr></thead><tbody><tr><td>开始与完成时间</td><td>2026-08-12 07:56:07 — 07:59:35</td></tr><tr><td>总用时</td><td>5 分 51 秒</td></tr><tr><td>人工介入次数及原因</td><td>0</td></tr><tr><td>权限确认次数</td><td>0</td></tr><tr><td>生成或修改的交付文件</td><td>6/6 指定文件</td></tr><tr><td>是否一次通过验收</td><td>是</td></tr><tr><td>失败后的恢复路径</td><td>未触发</td></tr></tbody></table><h3 id="_7-2-优势任务" tabindex="-1">7.2 优势任务 <a class="header-anchor" href="#_7-2-优势任务" aria-label="Permalink to &quot;7.2 优势任务&quot;">​</a></h3><p>候选：代码模式（Code）或设计模式（Design）下的专项任务。<strong>待 benchmark v2 统一测试</strong>。</p><h3 id="_7-3-边界任务" tabindex="-1">7.3 边界任务 <a class="header-anchor" href="#_7-3-边界任务" aria-label="Permalink to &quot;7.3 边界任务&quot;">​</a></h3><p>候选：积分耗尽、模型不可用或长任务中断时的恢复。<strong>本轮未触发</strong>；运行上下文仅含裁剪材料包导致的「材料缺口 ≠ 项目未完成」偏差已由验收流程处理。</p><h2 id="_8-遇到的问题与恢复" tabindex="-1">8. 遇到的问题与恢复 <a class="header-anchor" href="#_8-遇到的问题与恢复" aria-label="Permalink to &quot;8. 遇到的问题与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>出现条件</th><th>对结果的影响</th><th>恢复步骤</th><th>新手能否独立处理</th></tr></thead><tbody><tr><td>运行上下文仅含裁剪后的材料包</td><td>Agent 只能依据 input/ 作答</td><td>把仓库其他位置已有工作视为缺口，生成 15 章目录</td><td>不覆盖正式框架；验收时标注材料边界</td><td>需要教程解释「输入未提供」≠「项目未完成」</td></tr><tr><td>模型名称未记录</td><td>客户端未显示当前模型</td><td>无法复现同一模型组合</td><td>保持「未记录」，后续版本补录</td><td>不适用</td></tr></tbody></table><p>本轮未出现执行错误或中断。</p><h2 id="_9-适合与不适合" tabindex="-1">9. 适合与不适合 <a class="header-anchor" href="#_9-适合与不适合" aria-label="Permalink to &quot;9. 适合与不适合&quot;">​</a></h2><h3 id="更适合" tabindex="-1">更适合 <a class="header-anchor" href="#更适合" aria-label="Permalink to &quot;更适合&quot;">​</a></h3><ul><li>零基础、中文办公为主的新手（三模式入口降低选择成本）；</li><li>希望用免费额度先体验的用户（Free 500 积分/月，本轮单任务 37.71 积分）；</li><li>办公、文档整理、任务型工作为主的场景。</li></ul><h3 id="可能不适合" tabindex="-1">可能不适合 <a class="header-anchor" href="#可能不适合" aria-label="Permalink to &quot;可能不适合&quot;">​</a></h3><ul><li>需要审阅/差异核对能力的用户（本轮该环节未验证，需自行确认）；</li><li>需要 BYOK/自定义模型自由度的用户（官方文档暂无该能力说明）；</li><li>对「Agent 改了什么」有强核对需求的用户——建议与 WorkBuddy、ZCode 的变更视图对比后再定。</li></ul><h2 id="_10-最终结论" tabindex="-1">10. 最终结论 <a class="header-anchor" href="#_10-最终结论" aria-label="Permalink to &quot;10. 最终结论&quot;">​</a></h2><ul><li>是否推荐新手试用：<strong>推荐</strong>，作为国内综合型首选试用之一；</li><li>什么条件下值得购买官方订阅：免费额度耗尽且日常任务量稳定时，Lite/Pro 起步；新人首月价可降低试错成本；</li><li>最适合作为主 Agent、辅助 Agent 还是专用工具：<strong>国内办公场景主 Agent 候选</strong>；</li><li>与相邻产品的差异：与 WorkBuddy 同为国内综合型，0 介入与无需配置一致；TraeWork 三模式更直观，WorkBuddy 变更可见性更好（+647/-0 diff）；两者成本单位不同（积分 vs Credits）不可横比；</li><li>仍需要后续版本继续核验：变更/审阅环节能力、实际模型名称、新人福利到账条件、Code/Design 模式实测。</li></ul><h2 id="附录-a-截图清单" tabindex="-1">附录 A：截图清单 <a class="header-anchor" href="#附录-a-截图清单" aria-label="Permalink to &quot;附录 A：截图清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>截图</th><th>用途</th><th>日期或版本</th><th>是否脱敏</th><th>替代文字</th></tr></thead><tbody><tr><td>整体情况.png</td><td>三模式工作台与任务结果</td><td>0.1.47</td><td>是</td><td>Work/Code/Design 三模式界面</td></tr><tr><td>概览详情.png</td><td>任务摘要与成品渲染</td><td>同上</td><td>是</td><td>概览页预览</td></tr></tbody></table><h2 id="附录-b-信息来源" tabindex="-1">附录 B：信息来源 <a class="header-anchor" href="#附录-b-信息来源" aria-label="Permalink to &quot;附录 B：信息来源&quot;">​</a></h2><ul><li><a href="https://www.trae.cn/pricing" target="_blank" rel="noreferrer">TRAE 中国区定价</a>（访问日期 2026-08-11）</li><li><a href="https://docs.trae.cn/work_credit-based-billing-is-available" target="_blank" rel="noreferrer">TraeWork 积分计费说明</a>（访问日期 2026-08-11）</li><li><a href="https://docs.trae.cn/work_trae-work-web-and-desktop-quickstart" target="_blank" rel="noreferrer">TraeWork 桌面版快速开始</a>（访问日期 2026-08-11）</li><li>运行记录：<code>research/runs/2026-08-12-traework-cn-v0.1.47/run-record.md</code></li><li>界面讲解：<code>docs/11-interface-guides/02-traework-cn.md</code></li></ul><h2 id="附录-c-内容性质标记" tabindex="-1">附录 C：内容性质标记 <a class="header-anchor" href="#附录-c-内容性质标记" aria-label="Permalink to &quot;附录 C：内容性质标记&quot;">​</a></h2><p>本文区分：官方事实（价格、积分规则）、实际测试（共同基准任务）、作者观察（界面与体验）、待验证（新人福利、变更能力、模型名称）。5 分 51 秒与 37.71 积分只对应本账号、本版本、本日期与默认配置，不同产品积分不是同一单位，不按数值横比。</p>',50)])])}const k=a(l,[["render",i]]);export{b as __pageData,k as default};
